import{_ as o,o as d,c,a5 as n}from"./chunks/framework.DJo0M80U.js";const r=JSON.parse('{"title":"windows下nginx的安装及使用","description":"","frontmatter":{"title":"windows下nginx的安装及使用","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","构建运维","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第七部分：构建与运维/03-Nginx/windows下nginx的安装及使用.md","filePath":"posts/java快速入门/第七部分：构建与运维/03-Nginx/windows下nginx的安装及使用.md"}'),i={name:"posts/java快速入门/第七部分：构建与运维/03-Nginx/windows下nginx的安装及使用.md"};function t(a,e,l,g,p,s){return d(),c("div",null,[...e[0]||(e[0]=[n('<div><p><code>1.</code>下载</p><p>nginx <a href="http://nginx.org/en/download.html" target="_blank" rel="noreferrer">http://nginx.org/en/download.html</a>  下载稳定版本，以</p><p><code>nginx/Windows-1.12.2</code></p><p>为例，直接下载 <code>nginx-1.12.2.zip</code> 下载后解压，解压后如下</p><p><code>2.</code>启动<code>nginx</code> 有很多种方法启动</p><ul><li>nginx</li><li>(1)</li></ul><p>直接双击<code>nginx.exe</code>，双击后一个黑色的弹窗一闪而过 <code>(2)</code>打开<code>cmd</code>命令窗口，切换到<code>nginx</code>解压目录下，输入命令 <code>nginx.exe</code> 或者 <code>start nginx</code> ，回车即可 <code>3.</code>检查<code>nginx</code>是否启动成功 直接在浏览器地址栏输入网址</p><p><a href="http://localhost:80" target="_blank" rel="noreferrer">http://localhost:80</a> ，回车，出现以下页面说明启动成功</p><p>也可以在<code>cmd</code>命令窗口输入命令 <code>tasklist /fi &quot;imagename eq nginx.exe&quot;</code> ，出现如下结果说明启动成功</p><p><code>nginx</code>的配置文件是<code>conf</code>目录下的<code>nginx.conf</code>，默认配置的<code>nginx</code>监听的端口为<code>80</code>，如果<code>80</code>端口被占用可以修改为未被占用的端口即可；</p><p>检查<code>80</code>端口是否被占用的命令是： <code>netstat -ano | findstr 0.0.0.0:80</code> 或 <code>netstat -ano | findstr &quot;80&quot;</code> 当我们修改了<code>nginx</code>的配置文件<code>nginx.conf</code> 时，不需要关闭<code>nginx</code>后重新启动<code>nginx</code>，只需要执行命令 <code>nginx -s reload</code> 即可让改动生效 <code>4.</code>关闭<code>nginx</code> 如果使用<code>cmd</code>命令窗口启动<code>nginx</code>，关闭<code>cmd</code>窗口是不能结束<code>nginx</code>进程的，可使用两种方法关闭</p><ul><li>nginx</li><li>(1)</li></ul><p>输入<code>nginx</code>命令  <code>nginx -s stop(</code>快速停止<code>nginx)</code>  或  <code>nginx -s quit(</code>完整有序的停止</p><ul><li>nginx)</li><li>(2)</li></ul><p>使用<code>taskkill</code></p><ul><li>taskkill /f /t /im nginx.exe</li><li><ol start="5"><li></li></ol></li></ul><p>使用<code>nginx</code>代理服务器做负载均衡 我们可以修改<code>nginx</code>的配置文件<code>nginx.conf</code> 达到访问<code>nginx</code>代理服务器时跳转到指定服务器的目的，即通过<code>proxy_pass</code> 配置请求转发地址，即当我们依然输入<code>http://localhost:80</code> 时，请求会跳转到我们配置的服务器  同理，我们可以配置多个目标服务器，当一台服务器出现故障时，<code>nginx</code>能将请求自动转向另一台服务器，例如配置如下：</p><p>当服务器 <code>localhost:8080</code> 挂掉时，<code>nginx</code>能将请求自动转向服务器 <code>192.168.101.9:8080</code> 。上面还加了一个<code>weight</code>属性，此属性表示各服务器被访问到的权重，<code>weight</code> 越高被访问到的几率越高。 <code>6.nginx</code>配置静态资源  将静态资源（如<code>jpg|png|css|js</code>等）放在如下配置的<code>f:/nginx-1.12.2/static</code>目录下，然后在<code>nginx</code>配置文件中做如下配置<code>(</code>注意：静态资源配置只能放在 <code>location /</code> 中<code>)</code>，浏览器中访问</p><p><a href="http://localhost:80/1.png" target="_blank" rel="noreferrer">http://localhost:80/1.png</a> 即可访问到 <code>f:/nginx-1.12.2/static</code>目录下的 <code>1.png</code>图片</p></div>',1)])])}const _=o(i,[["render",t]]);export{r as __pageData,_ as default};
